mapper.select:
SELECT s.id, s.name, s.student_no, s.gender, s.phone, s.class_id, c.class_name, s.enrollment_date, s.create_time, s.update_time, s.is_deleted FROM student s LEFT JOIN `class` c ON s.class_id = c.id AND c.is_deleted = 0 WHERE s.is_deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.class_id = #{classId}
ORDER BY s.id DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM student s WHERE s.is_deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.class_id = #{classId}

mapper.update:
UPDATE student
SET is_deleted = 1
WHERE id = #{id}
